// ============================================================================
// MÓDULO APROBAR MANTENIMIENTOS - HSLV
// Carga PDFs de mantenimientos preventivos, permite estampar sellos de
// aprobación (Biomédico / Infraestructura) y sube a "Mantenimiento Aprobado"
// ============================================================================
(function() {
  console.log('[APRO] aprobar-mantenimientos.js cargando...');
  if (window.__HSLV_APRO_LOADED) { console.log('[APRO] Ya cargado'); return; }
  window.__HSLV_APRO_LOADED = true;

  const BASE = typeof API_BASE_URL !== 'undefined' ? API_BASE_URL : '/.netlify/functions';
  const FIELD_PREV = 'Mantenimientos preventivo';
  const FIELD_APROBADO = 'Mantenimiento Aprobado';

  const aproState = {
    records: [],
    loaded: false,
    selectedRecord: null,
    selectedSello: null,
  };

  // ── Sellos en Base64 ──
  const SELLO_BIOMEDICO = 'data:image/png;base64,';
  const SELLO_INFRAESTRUCTURA = 'data:image/png;base64,';

  function hdr() { try { if(typeof getAuthHeader==='function') return getAuthHeader(); } catch(e){} return {}; }
  function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

  // ══════════════════════════════════════════════════════════════════════
  // CARGAR MÓDULO
  // ══════════════════════════════════════════════════════════════════════
  async function loadAprobarModule(force) {
    var body = document.getElementById('aprobarBody');
    if (!body) return;

    if (!aproState.loaded || force) {
      body.innerHTML = '<div style="text-align:center;padding:60px"><div class="mt-spinner" style="width:40px;height:40px;border-width:4px;margin:0 auto 16px"></div><div style="color:#78909c;font-size:14px">Cargando mantenimientos preventivos...</div></div>';

      try {
        var inv = [], ioff = null;
        do {
          var p = new URLSearchParams({pageSize:'100'}); if(ioff) p.set('offset',ioff);
          var r = await axios.get(BASE+'/inventario?'+p, {headers:hdr()});
          var d = r.data||{};
          inv = inv.concat(d.records||d.data||[]);
          ioff = d.offset||null;
        } while(ioff);

        // Extraer solo los que tienen preventivos
        aproState.records = [];
        inv.forEach(function(rec) {
          var f = rec.fields||{};
          var equipo = f['Equipo']||f['EQUIPO']||'';
          var placa = f['Numero de Placa']||f['PLACA']||'';
          var servicio = f['Servicio']||f['SERVICIO']||'';
          var prevs = f[FIELD_PREV]||[];
          var aprobados = f[FIELD_APROBADO]||[];
          var aprobadosNames = aprobados.map(function(a){ return a.filename||''; });

          prevs.forEach(function(att) {
            var fn = att.filename||att.name||'reporte.pdf';
            var aprobadoName = fn.replace(/\.pdf$/i, '_APROBADO.pdf');
            var yaAprobado = aprobadosNames.some(function(n){ return n === aprobadoName || n === fn; });
            aproState.records.push({
              id: att.id||att.url,
              equipoId: rec.id,
              equipo: equipo,
              placa: placa,
              servicio: servicio,
              filename: fn,
              url: att.url,
              size: att.size,
              aprobado: yaAprobado,
              fecha: extractDate(fn),
            });
          });
        });
        aproState.records.sort(function(a,b){ return (b.fecha||'').localeCompare(a.fecha||''); });
        aproState.loaded = true;
      } catch(err) {
        body.innerHTML = '<div style="text-align:center;padding:40px;color:#c62828">⚠️ Error al cargar<br><small>'+esc(err&&err.message||'')+'</small><br><button onclick="loadAprobarModule(true)" style="margin-top:12px;padding:8px 20px;background:#1565c0;color:white;border:none;border-radius:8px;cursor:pointer;font-weight:600">🔄 Reintentar</button></div>';
        return;
      }
    }
    renderAprobarList();
  }

  function extractDate(fn) { var m=fn.match(/(\d{4}-\d{2}-\d{2})/); return m?m[1]:''; }
  function fmtDate(v) { if(!v)return''; if(/^\d{4}-\d{2}-\d{2}$/.test(v)){var p=v.split('-');return parseInt(p[2])+'/'+parseInt(p[1])+'/'+p[0];} return v; }

  // ══════════════════════════════════════════════════════════════════════
  // RENDERIZAR LISTA
  // ══════════════════════════════════════════════════════════════════════
  function renderAprobarList() {
    var body = document.getElementById('aprobarBody');
    if (!body) return;

    var total = aproState.records.length;
    var aprobados = aproState.records.filter(function(r){ return r.aprobado; }).length;
    var pendientes = total - aprobados;

    var statsHTML = '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px">'
      + '<div style="background:white;border-radius:12px;padding:16px;text-align:center;box-shadow:0 2px 8px rgba(0,0,0,0.06);border:1px solid #e0e0e0"><div style="font-size:24px;font-weight:800;color:#1565c0">'+total+'</div><div style="font-size:11px;color:#78909c;font-weight:600;text-transform:uppercase;letter-spacing:.5px;margin-top:4px">Total Reportes</div></div>'
      + '<div style="background:white;border-radius:12px;padding:16px;text-align:center;box-shadow:0 2px 8px rgba(0,0,0,0.06);border:1px solid #e0e0e0"><div style="font-size:24px;font-weight:800;color:#f57f17">'+pendientes+'</div><div style="font-size:11px;color:#78909c;font-weight:600;text-transform:uppercase;letter-spacing:.5px;margin-top:4px">Pendientes</div></div>'
      + '<div style="background:white;border-radius:12px;padding:16px;text-align:center;box-shadow:0 2px 8px rgba(0,0,0,0.06);border:1px solid #e0e0e0"><div style="font-size:24px;font-weight:800;color:#2e7d32">'+aprobados+'</div><div style="font-size:11px;color:#78909c;font-weight:600;text-transform:uppercase;letter-spacing:.5px;margin-top:4px">Aprobados</div></div>'
      + '</div>';

    if (total === 0) {
      body.innerHTML = statsHTML + '<div style="text-align:center;padding:60px;color:#90a4ae"><div style="font-size:48px;margin-bottom:12px">📋</div><div style="font-size:16px;font-weight:600">No hay reportes preventivos</div><div style="font-size:13px;margin-top:6px">Los reportes aparecerán aquí cuando se generen desde Mantenimientos.</div></div>';
      return;
    }

    var rows = aproState.records.map(function(r, i) {
      var estadoBadge = r.aprobado
        ? '<span style="display:inline-block;padding:3px 10px;border-radius:10px;font-size:10px;font-weight:700;background:#e8f5e9;color:#2e7d32">✅ Aprobado</span>'
        : '<span style="display:inline-block;padding:3px 10px;border-radius:10px;font-size:10px;font-weight:700;background:#fff3e0;color:#f57f17">⏳ Pendiente</span>';
      var btnAprobar = r.aprobado
        ? ''
        : '<button onclick="openAprobarModal('+i+')" style="padding:6px 14px;background:#2e7d32;color:white;border:none;border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap">✅ Aprobar</button>';
      var sizeKB = r.size ? (r.size/1024).toFixed(0)+' KB' : '—';
      return '<tr style="border-bottom:1px solid #f0f0f0">'
        + '<td style="padding:10px 12px;font-weight:700;font-size:12px;color:#263238">'+esc(r.equipo)+'<div style="font-size:10px;font-weight:400;color:#90a4ae">'+esc(r.placa)+'</div></td>'
        + '<td style="padding:10px 8px;font-size:12px;color:#546e7a">'+esc(r.servicio)+'</td>'
        + '<td style="padding:10px 8px;font-size:12px;color:#546e7a;text-align:center">'+fmtDate(r.fecha)+'</td>'
        + '<td style="padding:10px 8px;font-size:11px;color:#78909c;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+esc(r.filename)+'">'+esc(r.filename)+'</td>'
        + '<td style="padding:10px 8px;font-size:11px;color:#90a4ae;text-align:center">'+sizeKB+'</td>'
        + '<td style="padding:10px 8px;text-align:center">'+estadoBadge+'</td>'
        + '<td style="padding:10px 8px;text-align:center;white-space:nowrap">'
        + (r.url?'<a href="'+esc(r.url)+'" target="_blank" style="margin-right:6px;font-size:16px;text-decoration:none" title="Ver PDF">📄</a>':'')
        + btnAprobar
        + '</td></tr>';
    }).join('');

    body.innerHTML = statsHTML
      + '<div style="background:white;border-radius:12px;box-shadow:0 2px 12px rgba(0,0,0,0.06);overflow:hidden;border:1px solid #e0e0e0">'
      + '<table style="width:100%;border-collapse:collapse"><thead><tr style="background:#eceff1">'
      + '<th style="padding:10px 12px;text-align:left;font-size:10px;font-weight:700;color:#37474f;text-transform:uppercase;letter-spacing:.5px">Equipo</th>'
      + '<th style="padding:10px 8px;text-align:left;font-size:10px;font-weight:700;color:#37474f;text-transform:uppercase;letter-spacing:.5px">Servicio</th>'
      + '<th style="padding:10px 8px;text-align:center;font-size:10px;font-weight:700;color:#37474f;text-transform:uppercase;letter-spacing:.5px">Fecha</th>'
      + '<th style="padding:10px 8px;text-align:left;font-size:10px;font-weight:700;color:#37474f;text-transform:uppercase;letter-spacing:.5px">Archivo</th>'
      + '<th style="padding:10px 8px;text-align:center;font-size:10px;font-weight:700;color:#37474f;text-transform:uppercase;letter-spacing:.5px">Tamaño</th>'
      + '<th style="padding:10px 8px;text-align:center;font-size:10px;font-weight:700;color:#37474f;text-transform:uppercase;letter-spacing:.5px">Estado</th>'
      + '<th style="padding:10px 8px;text-align:center;font-size:10px;font-weight:700;color:#37474f;text-transform:uppercase;letter-spacing:.5px">Acciones</th>'
      + '</tr></thead><tbody>'+rows+'</tbody></table></div>';
  }

  // ══════════════════════════════════════════════════════════════════════
  // MODAL DE APROBACIÓN
  // ══════════════════════════════════════════════════════════════════════
  window.openAprobarModal = function(idx) {
    var r = aproState.records[idx];
    if (!r) return;
    aproState.selectedRecord = r;
    aproState.selectedSello = null;

    // Remover modal anterior
    var old = document.getElementById('aprobarModal');
    if (old) old.remove();

    var modal = document.createElement('div');
    modal.id = 'aprobarModal';
    modal.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.6);z-index:99999;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(3px);';
    modal.innerHTML = '<div style="background:white;border-radius:16px;max-width:600px;width:95%;max-height:90vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,0.3);position:relative">'
      + '<div style="padding:20px 24px;border-bottom:2px solid #e8eaf6">'
      + '<div style="display:flex;justify-content:space-between;align-items:center">'
      + '<h3 style="margin:0;font-size:18px;color:#1a237e;font-weight:800">✅ Aprobar Mantenimiento</h3>'
      + '<button onclick="closeAprobarModal()" style="background:none;border:none;font-size:24px;cursor:pointer;color:#90a4ae;padding:4px">&times;</button>'
      + '</div></div>'
      + '<div style="padding:24px">'
      // Info del equipo
      + '<div style="background:#f5f5f5;border-radius:10px;padding:14px 16px;margin-bottom:20px">'
      + '<div style="font-size:13px;font-weight:700;color:#263238">'+esc(r.equipo)+'</div>'
      + '<div style="font-size:11px;color:#78909c;margin-top:3px">'+esc(r.servicio)+' · '+esc(r.placa)+' · '+fmtDate(r.fecha)+'</div>'
      + '<div style="font-size:10px;color:#90a4ae;margin-top:3px;word-break:break-all">'+esc(r.filename)+'</div>'
      + '</div>'
      // Seleccionar sello
      + '<div style="font-size:13px;font-weight:700;color:#37474f;margin-bottom:12px;text-transform:uppercase;letter-spacing:.5px">Seleccionar sello de aprobación:</div>'
      + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:24px">'
      + '<div id="selloBioCard" onclick="selectSello(\'biomedico\')" style="cursor:pointer;border:3px solid #e0e0e0;border-radius:12px;padding:16px;text-align:center;transition:all 0.2s;background:white">'
      + '<img src="'+SELLO_BIOMEDICO+'" style="max-width:140px;max-height:140px;margin:0 auto;display:block">'
      + '<div style="margin-top:8px;font-size:11px;font-weight:700;color:#2e7d32">Líder Biomédico</div>'
      + '</div>'
      + '<div id="selloInfraCard" onclick="selectSello(\'infraestructura\')" style="cursor:pointer;border:3px solid #e0e0e0;border-radius:12px;padding:16px;text-align:center;transition:all 0.2s;background:white">'
      + '<img src="'+SELLO_INFRAESTRUCTURA+'" style="max-width:140px;max-height:140px;margin:0 auto;display:block">'
      + '<div style="margin-top:8px;font-size:11px;font-weight:700;color:#1565c0">Líder Infraestructura</div>'
      + '</div>'
      + '</div>'
      // Botones
      + '<div style="display:flex;gap:12px;justify-content:flex-end">'
      + '<button onclick="closeAprobarModal()" style="padding:10px 24px;background:#eceff1;color:#546e7a;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer">Cancelar</button>'
      + '<button id="btnConfirmAprobar" onclick="confirmarAprobacion()" disabled style="padding:10px 24px;background:#bdbdbd;color:white;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:not-allowed;transition:all 0.2s">🔏 Aprobar y Guardar</button>'
      + '</div>'
      + '</div></div>';

    document.body.appendChild(modal);
    modal.addEventListener('click', function(e) { if(e.target===modal) closeAprobarModal(); });
  };

  window.closeAprobarModal = function() {
    var m = document.getElementById('aprobarModal');
    if (m) m.remove();
  };

  window.selectSello = function(tipo) {
    aproState.selectedSello = tipo;
    var bioCard = document.getElementById('selloBioCard');
    var infraCard = document.getElementById('selloInfraCard');
    var btn = document.getElementById('btnConfirmAprobar');

    if (bioCard) bioCard.style.borderColor = tipo==='biomedico' ? '#2e7d32' : '#e0e0e0';
    if (bioCard) bioCard.style.background = tipo==='biomedico' ? '#f1f8e9' : 'white';
    if (infraCard) infraCard.style.borderColor = tipo==='infraestructura' ? '#1565c0' : '#e0e0e0';
    if (infraCard) infraCard.style.background = tipo==='infraestructura' ? '#e3f2fd' : 'white';

    if (btn) {
      btn.disabled = false;
      btn.style.background = tipo==='biomedico' ? '#2e7d32' : '#1565c0';
      btn.style.cursor = 'pointer';
    }
  };

  // ══════════════════════════════════════════════════════════════════════
  // CONFIRMAR APROBACIÓN — Descargar PDF, estampar sello, subir
  // ══════════════════════════════════════════════════════════════════════
  window.confirmarAprobacion = async function() {
    var r = aproState.selectedRecord;
    var selloTipo = aproState.selectedSello;
    if (!r || !selloTipo) return;

    var btn = document.getElementById('btnConfirmAprobar');
    if (btn) { btn.disabled = true; btn.innerHTML = '<span style="display:inline-flex;align-items:center;gap:6px"><span class="mt-spinner" style="width:16px;height:16px;border-width:2px"></span>Procesando...</span>'; }

    try {
      // 1. Descargar el PDF original
      if (btn) btn.innerHTML = '<span style="display:inline-flex;align-items:center;gap:6px"><span class="mt-spinner" style="width:16px;height:16px;border-width:2px"></span>Descargando PDF...</span>';
      var pdfResponse = await fetch(r.url);
      var pdfBytes = await pdfResponse.arrayBuffer();

      // 2. Cargar pdf-lib si no está disponible
      if (typeof PDFLib === 'undefined') {
        if (btn) btn.innerHTML = '<span style="display:inline-flex;align-items:center;gap:6px"><span class="mt-spinner" style="width:16px;height:16px;border-width:2px"></span>Cargando librería...</span>';
        await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js');
      }

      // 3. Modificar el PDF — añadir sello
      if (btn) btn.innerHTML = '<span style="display:inline-flex;align-items:center;gap:6px"><span class="mt-spinner" style="width:16px;height:16px;border-width:2px"></span>Estampando sello...</span>';

      var selloImgUrl = selloTipo === 'biomedico' ? SELLO_BIOMEDICO : SELLO_INFRAESTRUCTURA;
      var selloImgBytes = await fetch(selloImgUrl).then(function(r){ return r.arrayBuffer(); });

      var pdfDoc = await PDFLib.PDFDocument.load(pdfBytes);
      var selloImg = await pdfDoc.embedPng(selloImgBytes);
      var pages = pdfDoc.getPages();

      // Estampar en la última página
      var lastPage = pages[pages.length - 1];
      var pageW = lastPage.getWidth();
      var pageH = lastPage.getHeight();

      // Sello de 120x120 en esquina inferior derecha
      var selloSize = 120;
      var selloX = pageW - selloSize - 40;
      var selloY = 40;

      lastPage.drawImage(selloImg, {
        x: selloX,
        y: selloY,
        width: selloSize,
        height: selloSize,
        opacity: 0.85,
      });

      var modifiedPdfBytes = await pdfDoc.save();

      // 4. Convertir a base64
      if (btn) btn.innerHTML = '<span style="display:inline-flex;align-items:center;gap:6px"><span class="mt-spinner" style="width:16px;height:16px;border-width:2px"></span>Subiendo a Airtable...</span>';
      var blob = new Blob([modifiedPdfBytes], {type:'application/pdf'});
      var base64 = await new Promise(function(resolve, reject) {
        var reader = new FileReader();
        reader.onload = function(){ resolve(reader.result.split(',')[1]); };
        reader.onerror = reject;
        reader.readAsDataURL(blob);
      });

      // 5. Subir a Airtable campo "Mantenimiento Aprobado"
      var aprobadoFilename = r.filename.replace(/\.pdf$/i, '_APROBADO.pdf');
      var uploadRes = await axios.post(BASE+'/upload-pdf', {
        recordId: r.equipoId,
        fieldName: FIELD_APROBADO,
        filename: aprobadoFilename,
        contentType: 'application/pdf',
        base64: base64,
      }, { headers: hdr() });

      if (!uploadRes.data.ok) throw new Error(uploadRes.data.error||'Error al subir');

      // 6. Marcar como aprobado
      r.aprobado = true;
      closeAprobarModal();
      showAproToast('✅ Mantenimiento aprobado y guardado en Airtable', 'ok');
      renderAprobarList();

    } catch(err) {
      console.error('[APRO] Error:', err);
      showAproToast('❌ Error: '+(err.message||'Error desconocido'), 'err');
      if (btn) { btn.disabled = false; btn.innerHTML = '🔏 Aprobar y Guardar'; btn.style.cursor = 'pointer'; }
    }
  };

  function loadScript(src) {
    return new Promise(function(resolve, reject) {
      if (document.querySelector('script[src="'+src+'"]')) { resolve(); return; }
      var s = document.createElement('script');
      s.src = src;
      s.onload = resolve;
      s.onerror = function(){ reject(new Error('No se pudo cargar: '+src)); };
      document.head.appendChild(s);
    });
  }

  function showAproToast(msg, type) {
    var t = document.getElementById('aproToast');
    if (!t) { t = document.createElement('div'); t.id = 'aproToast'; document.body.appendChild(t); }
    var bg = type==='ok'?'#2e7d32':type==='warn'?'#f57f17':'#c62828';
    t.style.cssText = 'position:fixed;bottom:32px;right:32px;background:'+bg+';color:white;padding:14px 22px;border-radius:10px;font-size:14px;font-weight:600;font-family:Outfit,sans-serif;z-index:999999;box-shadow:0 8px 24px rgba(0,0,0,0.2);transition:opacity 0.4s;opacity:1;max-width:400px';
    t.textContent = msg;
    clearTimeout(t._to);
    t._to = setTimeout(function(){ t.style.opacity = '0'; }, 4000);
  }

  window.loadAprobarModule = loadAprobarModule;
})();
